10. get_service_metrics({"service":"feeds-worker"}) -> {"service":"feeds-worker","status":"degraded","error_rate":0.1974,"p95_latency_ms":657.0,"cpu_pct":44.5,"restarts_last_15m":10,"replicas":4}
